import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int nChars = Integer.parseInt(br.readLine());
        int maxLen = 0, totalWords = 0, outsideCount = 0, insideCount = 0;
        boolean insideParenthesesFlag = false;
        String inputLine = br.readLine();
        char[] inputChars = inputLine.toCharArray();

        for (int index = 0; index < nChars; index++) {
            char currentChar = inputChars[index];
            if (currentChar == '(') {
                insideParenthesesFlag = true;
                outsideCount = 0;
            } else if (currentChar == ')') {
                insideParenthesesFlag = false;
                if (insideCount > 0) {
                    totalWords++;
                    insideCount = 0;
                }
            } else {
                if (insideParenthesesFlag) {
                    if (currentChar != '_') {
                        insideCount++;
                    } else {
                        if (insideCount > 0) {
                            totalWords++;
                            insideCount = 0;
                        }
                    }
                } else {
                    if (currentChar != '_') {
                        outsideCount++;
                    } else {
                        outsideCount = 0;
                    }
                }
            }
            if (outsideCount >= maxLen) {
                maxLen = outsideCount;
            }
        }
        System.out.println(maxLen);
        System.out.println(totalWords);
    }
}
